    # Ensure that the input is a float or an integer
    if not isinstance(num, (int, float)):
        return False

    # Check for NaN values
    if math.isnan(num):
        return False

    # Check for infinite values
    if math.isinf(num):
        return False

    # Ensure the number has exactly 2 decimal places
    try:
        # Convert the number to a string and split it at the decimal point
        parts = str(num).split('.')

        # If there's no decimal point, or more than one, it's not a valid decimal
        if len(parts) != 2 or len(parts[1]) != 2:
            return False

        # Check if both parts are digits
        return all(c.isdigit() for c in parts)
    except ValueError:
        # If conversion fails, it's not a valid number
        return False
